/*
 * CP932 (Windows Shift-JIS) to UTF-8. Tables are generated by gen_cp932.py (next to this file).
 */
#pragma once

#include "core/ft_common.h"

/* Lead bytes 0x81-0x9F and 0xE0-0xFC; trail bytes 0x40-0xFC. 0 = unmapped. */
extern const uint16_t ft_cp932_single[256];
extern const uint16_t ft_cp932_double[60][189];

/*
 * Converts `len` CP932 bytes to a NUL-terminated malloc'd UTF-8 string.
 * Unmapped or truncated sequences become U+FFFD and are counted in *bad_out (may be NULL).
 */
char *ft_cp932_to_utf8(const uint8_t *src, size_t len, size_t *utf8_len_out, size_t *bad_out);
